/// Draws a 9 V PP3 battery with its snap clip, leads exiting to the left.
///
/// The artwork is vector paths generated by the Flutter Da Vinci Figma plugin
/// from the "Battery 9V" frame in the *PinBench Parts* Figma file — one layer
/// per colour, each shifted to where that layer sits in the frame. Redraw it
/// there and regenerate rather than hand-editing the coordinates.
///
/// Electrically an ideal source (see its entry in `standardParts`): it does not
/// sag under load or run down.
class Battery9vPainter({final Map<String, dynamic>? properties, super.isOutline})
    extends BaseComponentPainter
    with PortProvider, PathArtPainter {
  // The PP3 case is 48.5 × 26.5 mm; the footprint is rounded to whole hole
  // pitches (19 × 10) so both lead tips land on the connection lattice.
  static const width = 19 * GridSystem.pitch;
  static const height = 10 * GridSystem.pitch;
  static const componentSize = Size(width, height);

  // Lead tips, one hole pitch apart: black (−) above red (+).
  static const leadTipX = GridSystem.cellCenter;
  static const minusY = 4 * GridSystem.pitch + GridSystem.cellCenter;
  static const plusY = 5 * GridSystem.pitch + GridSystem.cellCenter;

  /// The case and clip; the leads hang off it to the ports.
  @override
  Rect bodyRect(Size size) => const Rect.fromLTRB(24, 8, width, 152);

  @override
  List<ComponentPort> getPorts() => const [
    ComponentPort(id: 'plus', name: '+', localOffset: Offset(leadTipX, plusY)),
    ComponentPort(id: 'minus', name: '-', localOffset: Offset(leadTipX, minusY)),
  ];

  @override
  Size get designSize => componentSize;

  @override
  List<PathArtLayer> get layers => _layers;

  static final _layers = <PathArtLayer>[
    (_copper, const Color(0xFFCB804F)),
    (_polarityRings, const Color(0xFFAB6F48)),
    (_dark, const Color(0xFF2D2D2D)),
    (_terminalShadow, const Color(0xFF818181)),
    (_terminalFace, const Color(0xFFB1B1B1)),
    (_redLead, const Color(0xFFA5161F)),
    (_label, const Color(0xFFD8D8D8)),
  ];

  /// Copper cap over the terminal end.
