      ..moveTo(0, 5)
      ..cubicTo(0, 2.24, 2.24, 0, 5, 0)
      ..lineTo(74, 0)
      ..lineTo(74, 144)
      ..lineTo(5, 144)
      ..cubicTo(2.24, 144, 0, 141.76, 0, 139)
      ..lineTo(0, 5)
      ..close(),
  ]);

  /// Embossed rings around the polarity marks.
